-- Create Cases Table
CREATE TABLE IF NOT EXISTS public.cases (
  id serial PRIMARY KEY,
  title text NOT NULL,
  situation text NOT NULL,
  question text NOT NULL,
  options jsonb NOT NULL,
  correct_answer integer NOT NULL,
  explanation text
);

-- Disable Row Level Security
ALTER TABLE public.cases DISABLE ROW LEVEL SECURITY;

-- Grant permissions
GRANT ALL ON TABLE public.cases TO postgres, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.cases TO authenticated;
GRANT SELECT, INSERT ON TABLE public.cases TO anon;
GRANT USAGE, SELECT ON SEQUENCE public.cases_id_seq TO authenticated, anon, service_role;

-- Seed cases if empty
INSERT INTO public.cases (title, situation, question, options, correct_answer, explanation)
SELECT title, situation, question, options, correct_answer, explanation FROM (
  VALUES
    ('Кейс 1. Захист персональних даних та робота з агресивним клієнтом', 'До фахівця звернувся ветеран Дмитро із проханням допомогти дізнатися статус заяви на отримання житлової пільги, яку подавав його побратим Сергій. Сергій зараз перебуває у шпиталі в іншій області й не має зв''язку, але йому терміново потрібна ця інформація. Дмитро має копію паспорта Сергія у своєму телефоні, але не має довіреності. Дмитро поводиться роздратовано і звинувачує фахівця у бюрократії.', 'Яка послідовність дій фахівця є найбільш професійною та відповідає закону?', '["Надати інформацію Дмитру, оскільки він є побратимом Сергія, має копію його паспорта і діє в його інтересах у критичній ситуації.", "Зареєструвати усне звернення Дмитра, зробити запит до бази даних та надіслати інформацію на особисту електронну адресу Дмитра.", "Висловити підтримку та співпереживання щодо стану Сергія; пояснити, що без офіційного представництва (довіреності) розголошення персональних даних заборонено законом; запропонувати допомогти Дмитру зв''язатися з соціальним працівником шпиталю, де лежить Сергій, або організувати відеодзвінок із Сергієм для отримання усної згоди чи допомогти оформити довіреність через керівництво/соцпрацівника шпиталю.", "Категорично відмовити Дмитру у зв''язку з Законом «Про захист персональних даних» і порадити Сергію особисто звернутися після виписки зі шпиталю."]'::jsonb, 2, 'Поєднання безкомпромісного дотримання Закону «Про захист персональних даних» з активним вирішенням проблеми (клієнтоорієнтованість). Пропонує легальні шляхи вирішення ситуації через адміністрацію медичного закладу та допомагає знизити рівень агресії Дмитра через виявлення емпатії.'),
    ('Кейс 2. Перша психологічна допомога при гострій реакції на стрес', 'Під час первинної зустрічі ветеран Олександр, який нещодавно демобілізувався, виглядає дуже напруженим. Він уникає зорового контакту, говорить уривчастими фразами, його руки помітно тремтять. Коли повз офіс гучно проїжджає вантажівка, Олександр різко здригається, хапається за стіл і застигає, важко дихаючи.', 'Яка послідовність дій є найбільш правильною з боку фахівця в цей момент?', '["Негайно обійняти Олександра, щоб дати йому відчуття безпеки, і голосно покликати колег на допомогу.", "Спокійним, рівним голосом звернутися до Олександра на ім''я, запропонувати зробити глибокий вдих і повільний видих разом із ним, назвати кілька предметів у кімнаті (використати техніку «заземлення») і почекати, поки дихання стабілізується, не торкаючись його без дозволу.", "Зробити вигляд, що нічого не сталося, продовжити заповнювати анкету первинного виявлення потреба, щоб не акцентувати увагу на його стані й не змушувати його ніяковіти.", "Запропонувати Олександру випити міцної кави або дати йому заспокійливе ліки з аптечки установи."]'::jsonb, 1, 'Це класичний протокол першої психологічної допомоги (ППД). Техніка «заземлення» повертає людину з флешбеку або панічної атаки в реальність. Фізичний контакт (обійми) без дозволу може сприйматися як загроза і посилити реакцію.'),
    ('Кейс 3. Захист прав ветеранів на міжміські перевезення', 'Ветеранка Тамара, яка отримала поранення та звільнилася зі служби зі статусом особи з інвалідністю внаслідок війни II групи, звернулася з проблемою: водій міжміського автобуса відмовив їй у безкоштовному проїзді, мотивуючи це тим, що ліміт пільгових місць (який начебто встановлений перевізником) на цей рейс уже вичерпано. Тамара обурена та хоче подати до суду на автопарк.', 'Що є найбільш конструктивним алгоритмом дій фахівця з супроводу?', '["Порадити Тамарі не витрачати час на суди, оскільки приватні перевізники мають право встановлювати власні квоти, та запропонувати їй компенсувати вартість квитка за рахунок місцевої благодійної програми.", "Допомогти Тамарі зафіксувати деталі інциденту (номер рейсу, держномер автобуса, ПІБ водія чи назву перевізника); скласти скаргу до Державної служби України з безпеки на транспорті (Укртрансбезпека) та до органів місцевої влади (замовника перевезень); роз''яснити їй, що закон не обмежує кількість пільгових місць для цієї категорії пасажирів.", "Порадити Тамарі викликати патрульну поліцію безпосередньо до автобуса під час наступного інциденту і заблокувати рух транспортного засобу до надання пільгового квитка.", "Особисто зателефонувати керівництву автотранспортного підприємства та погрожувати їм кримінальною відповідальністю, якщо вони не вибачаться перед ветеранкою."]'::jsonb, 1, 'Пільги на проїзд для осіб з інвалідністю внаслідок війни надаються без обмеження кількості місць на рейс. Конструктивний шлях — це правове вирішення через оргнани регулювання та контролю (Укртрансбезпеку та органи самоврядування).'),
    ('Кейс 4. Робота з кризовими сім''ями та етичні дилеми підпису документів', 'Фахівець здійснює супровід сім''ї загиблого Захисника (дружину Олену та двох дітей). Олена перебуває в стані глибокої апатії (синдром втрати), не виходить з дому і не може змусити себе зайнятися документами на отримання одноразової грошової допомоги. Термін подачі документів спливає. Двоюрідна сестра Олени просить фахівця передати їй бланки заяв, обіцяючи підписати їх замість Олени, щоб родина не втратила гроші.', 'Як має вчинити фахівець у межах кейс-менеджменту?', '["Передати бланки сестрі, оскільки фінансове благополуччя дітей є пріоритетом, а Олена згодом підтвердить це рішення усно.", "Заповнити та підписати заяви самостійно від імені Центру або як куратор сім''ї, посилаючись на форс-мажорні обставини та стан клієнтки.", "Організувати спільний візит із сестрою до Олени вдома; тактовно висловити підтримку, пояснити важливість дотримання термінів; допомогти Олені особисто заповнити та підписати документи на місці. Якщо її психологічний стан заважає прийняттю рішень — ініціювати термінове залучення мобільної бригади соціально-психологічної допомоги чи психолога.", "Повідомити орган опіки та піклування про неналежне виконання матір''ю своїх обов''язків щодо фінансового забезпечення дітей через її депресивний стан."]'::jsonb, 2, 'Підпис документів іншою особою є підробкою документів, що є протизаконним. Правильний варіант поєднує юридичну чистоту, психологічну підтримку та залучення суміжних спеціалістів (психологів) для стабілізації стану клієнтки.'),
    ('Кейс 5. Кар''єрна адаптація ветеранів з інвалідністю', 'Ветеран Ігор до служби працював автомеханіком. Внаслідок поранення він отримав ампутацію лівої руки нижче ліктя і більше не може виконувати колишню фізичну роботу. Ігор пригнічений, вважає себе «непридатним ні до чого», категорично відмовляється від пропозицій перенавчання на ІТ-спеціальності, зазначаючи, що «офісна робота — це не його», і він хоче працювати тільки в автосфері.', 'Яка стратегія профорієнтації з боку фахівця є найбільш ефективною та етичною?', '["Переконати Ігоря, що робота руками для нього завершена, і наполягти на його реєстрації на курси програмування чи тестування ПЗ як найбільш перспективних напрямках.", "Запропонувати Ігорю прості вакансії (наприклад, вахтера чи диспетчера), де фізичні обмеження не заважають роботі, а особливих навичок не потрібно.", "Детально проаналізувати його експертність у сфері авторемонту та запропонувати суміжні ролі в цій же галузі, які не потребують дрібної моторики лівої руки (наприклад, майстер-приймальник на СТО, менеджер з підбору та продажу автозапчастин, оцінювач пошкоджень для автострахування); допомогти підібрати відповідні короткі курси навчання для цих посад.", "Порадити Ігорю оформити максимальну пенсію по інвалідності й зосередитися на лікуванні, відклавши пошуки роботи на невизначений термін."]'::jsonb, 2, 'Ефективна адаптація базується на збереженні професійної ідентичності особи. Ігор має великий багаж знань про будову авто, тому використання його досвіду на посадах координаційного або консультаційного характеру в тій самій сфері полегшить адаптацію.'),
    ('Кейс 6. Консультування щодо ветеранського бізнесу та межі повноважень', 'Ветеран Сергій планує відкрити невелику ветеринарну клініку. Він дізнався від побратимів про державну програму грантів для ветеранів на створення власного бізнесу. Сергій приходить до фахівця Центру та вимагає, щоб той написав замість нього бізнес-план та подав заявку через Дію, аргументуючи це тим, що він «воював, поки інші вчилися писати бізнес-плани, і не розуміє цих фінансових таблиць».', 'Яка роль та алгоритм дій фахівця із супроводу в цій ситуації?', '["Написати бізнес-план та фінансові таблиці замість Сергія і надіслати заявку з власного робочого комп''ютера, щоб гарантувати отримання ветераном коштів.", "Пояснити Сергію, що розробка бізнес-проєктів не входить до обов''язків фахівця Центру; порадити йому звернутися до комерційної компанії, яка пише бізнес-плани за гроші.", "Зареєструвати Сергія на безкоштовні спеціалізовані бізнес-курси для ветеранів; надати йому детальну інструкцію щодо вимог гранту; допомогти розібратися зі структурою бізнес-плану; скоординувати його зустрічі з менторами-волонтерами, які допомагають ветеранам із розрахунками, залишаючи за Сергієм роль автора проєкту.", "Порадити Сергію не зв''язуватися з державними грантами через високий рівень бюрократії та перевірок, а натомість взяти споживчий кредит у банку на спрощених умовах."]'::jsonb, 2, 'Мета супроводу — розширення спроможності ветерана (empowerment) та відновлення його самостійності, а не виконання роботи за нього. Фахівець виступає навігатором: направляє на навчання, координує з експертами та допомагає розібратися.'),
    ('Кейс 7. Коригування індивідуального плану супроводу', 'Ветеран Андрій проходить супровід у Центрі. Згідно з його індивідуальним планом, пріоритетами були санаторно-курортне лікування для відновлення опорно-рухового апарату та подальше працевлаштування. Під час моніторингового дзвінка фахівець дізнається, що Андрій відмовився від путівки в санаторій, оскільки «не хоче нікуди їхати», і не з''явився на жодну з трьох співбесід, організованих Центром зайнятості. Андрій каже, що «все це марно і нікому він не потрібен».', 'Які подальші дії фахівця в межах моніторингу та оцінювання потреб Андрія?', '["Зафіксувати порушення умов індивідуального плану, призупинити супровід і закрити справу у зв''язку з небажанням клієнта співпрацювати.", "Організувати особисту зустріч у комфортному для Андрія форматі; обговорити причини відмов; провести повторну оцінку його психологічного стану та потреба; скоригувати індивідуальний план (наприклад, тимчасово відтермінувати працевлаштування, натомість поставити пріоритетом роботу з психотерапевтом та залучення до ветеранської спільноти підтримки).", "Провести розмову з родичами Андрія (дружиною або батьками), щоб вони вплинули на нього та змусили поїхати в санаторій та пройти співбесіди.", "Наголосити Андрію, що відмова від виконання плану може призвести до негативних наслідків, зокрема до втрати статусу безробітного чи інших соціальних преференцій від держави."]'::jsonb, 1, 'Моніторинг спрямований на оцінку відповідності плану поточному стану клієнта. Відмова від плану часто свідчить про психологічну кризу. План має бути гнучким: спочатку стабілізація психологічного стану, а вже потім — працевлаштування.'),
    ('Кейс 8. Запобігання конфлікту інтересів та кумівству', 'До фахівця із супроводу звернувся його близький товариш та колишній однокласник Максим, який повернувся з зони бойових дій. Максим просить допомогти йому отримати матеріальну допомогу на лікування з місцевого бюджету позачергово, оскільки має великі борги. Фахівець знає, що черга на цю допомогу є великою, кошти обмежені, а інші ветерани чекають рішення комісії по 2-3 місяці. Максим просить «по-дружньому» прискорити розгляд та поставити його заяву першою.', 'Які дії фахівця відповідають стандартам професійної етики?', '["Допомогти Максиму та пересунути його заяву на початок списку, оскільки підтримка побратимів та друзів у скрутній ситуації є моральним пріоритетом.", "Пояснити Максиму, що це прямий конфлікт інтересів та порушення професійної етики, які можуть призвести до дисциплінарної відповідальності; допомогти йому оформити документи згідно з загальними вимогами; запропонувати передати його справу іншому фахівцю Центру для забезпечення прозорості та неупередженості.", "Відмовити Максиму у різкій формі, вказавши на неприпустимість корупційних прохань, та припинити будь-каке спілкування з ним.", "Прийняти документи Максима, пообіцяти допомогти, але свідомо затягувати процес розробки його кейсу, щоб заява пройшла в загальні терміни без скандалу."]'::jsonb, 1, 'Етичні стандарти вимагають уникати конфлікту інтересів. Найкраще рішення — допомогти другу оформити документи якісно, но передати ведення його кейсу іншому фахівцю, щоб зняти будь-які підозри в упередженості.'),
    ('Кейс 9. Профілактика професійного вигорання та саморегуляція', 'Фахівець працює із ветеранами вже понад півтора року. Останні кілька місяців він відчуває хронічну втому, яка не минає після вихідних, та часті головні болі. Історії клієнтів почали викликати у нього байдужість, а іноді — роздратування. Під час обговорення важкого кейсу колеги він цинічно зауважив: «Вони самі знали, куди йшли, нема чого тепер скаржитися». Раніше фахівець ніколи не дозволяв собі подібного.', 'Що має зробити фахівець у цій ситуації для відновлення своєї професійної придатності?', '["Проігнорувати цей стан як тимчасове перевтомлення, взяти додаткове навантаження, щоб довести свою стійкість, і заборонити собі думати про емоції.", "Усвідомити втрату емпатії як ознаку повної професійної непридатності та подати заяву на звільнення з соціальної сфери.", "Звернутися до керівництва Центру з проханням про позачергову індивідуальну супервізію; взяти щорічну відпустку для емоційного розвантаження; за рекомендацією супервізора скоригувати особисті межі у роботі з клієнтами та відвідати тренінг із профілактики синдрому емоційного вигорання (СЕВ).", "Почати приймати антидепресанти або седативні препарати за порадою колег, не звертаючись до профільних лікарів, щоб не псувати медичну карту."]'::jsonb, 2, 'Хронічна втома, втрата емпатії та цинізм є класичними ознаками синдрому емоційного вигорання (СЕВ). Професійний шлях вирішення — супервізія, плановий відпочинок та навчання навичкам саморегуляції.'),
    ('Кейс 10. Домашнє насильство та робота з родиною ветерана', 'До фахівця звернулася дружина ветерана Світлана. Вона розповіла, що після повернення чоловіка Валерія з фронту пів року тому життя в родині стало нестерпним. Валерій щодня вживає алкоголь, під час сп''яніння агресує, ображає її та дитину, кидає речі. Фізичного насильства (побоїв) ще не було, але Світлана дуже боїться за безпеку дитини. Валерій категорично відмовляється йти до психолога, заявляючи, що «в нього все нормально, а лікуватися треба їй».', 'Які дії фахівця є найбільш правильними та безпечними для клієнтки?', '["Особисто прийти до Валерія додому без попередження і провести з ним жорстку бесіду, погрожуючи поліцією та позбавленням батьківських прав, якщо він не припинить пити.", "Сфокусуватися на безпеці Світлани та дитини: допомогти розробити індивідуальний «план безпеки» на випадок загострення; надати контакти мобільних бригад протидії насильству, шелтерів та гарячої лінії 1547; запропонувати Світлані психологічную допомогу в групах підтримки для дружин ветеранів; проконсультувати щодо виклику спеціалізованого екіпажу поліції «ПОЛІНА».", "Порадити Світлані негайно подати на розлучення та виїхати з дитиною в інше місто, оскільки ветерани з алкогольною залежністю не піддаються реабілітації.", "Пояснити Світлані, що оскільки сам ветеран Валерій відмовляється від супроводу і не давав згоди на роботу з його родиною, Центр не має права втручатися в його особисте життя."]'::jsonb, 1, 'Безпека постраждалих від домашнього насильства є абсолютним пріоритетом. Особисте перевиховування агресора є небезпечним. Фахівець повинен надати Світлані інструменти захисту, контакти кризових служб та психологічну підтримку.')
) AS seed_data (title, situation, question, options, correct_answer, explanation)
WHERE NOT EXISTS (SELECT 1 FROM public.cases);
